import base64, json, os, runpy, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1",
                  HF_HOME="/tmp/e37-hf", OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e37-qwen")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e37")
for name, encoded in json.loads('{"datagen/extract_budget_path.py": "", "datagen/tokenizer_check.py": "", "datagen/perturb/answers.py": "", "datagen/perturb/sample.py": "", "datagen/extract_features.py": "", "train/eval_e36_budget_path.py": "", "protocols/E37_PROTOCOL.md": "", "data/train_main/rows.parquet": "", "data/train_main/provenance.json": "", "scripts/kaggle_cuda_setup.py": "", "scripts/kaggle_process_guard.py": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
cuda = runpy.run_path(str(root / "scripts/kaggle_cuda_setup.py"))["prepare_cuda_linker"]()
(out / "cuda-link-check.json").write_text(json.dumps(cuda, indent=2))
# CUDA 12 generation; avoid the CUDA 13 default wheels in newer vLLM releases.
subprocess.run([sys.executable, "-m", "venv", "--without-pip", "/tmp/e37-env"], check=True)
py = "/tmp/e37-env/bin/python"
subprocess.run([sys.executable, "-m", "pip", "--python", py, "install", "--no-cache-dir", "-q", "vllm==0.20.0",
               "transformers==5.13.0", "huggingface-hub==1.22.0", "scikit-learn==1.8.0",
               "pandas==3.0.3", "joblib==1.5.3", "pyarrow==24.0.0"], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "--python", py, "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
cmd = [py, "datagen/extract_budget_path.py", "--model-id", 'Qwen/Qwen3.5-4B',
       "--out-dir", str(out), "--tensor-parallel", "2", "--max-num-seqs", "2", "--chunk", "2"]
if 'qwen' == "qwen":
    cmd.append("--text-only")
result = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"](cmd, root, out / "runner.log")
(out / "execution.json").write_text(json.dumps({**result,
    "end_to_end_seconds": time.time() - started, "command": cmd}, indent=2))
raise SystemExit(result["exit_code"])
